export class ArchiveService {
  constructor(private readonly repository: ArchiveRepository) {}

  async list(): Promise<ServiceResult<ArchiveEntry[]>> {
    try {
      return { ok: true, value: (await this.repository.list()).map(copyEntry) };
    } catch {
      return { ok: false, reason: "storage_error" };
    }
  }

  async find(id: string): Promise<ServiceResult<ArchiveEntry>> {
    if (typeof id !== "string" || id.length === 0) {
      return { ok: false, reason: "invalid" };
    }
    try {
      const entry = await this.repository.find(id);
      return entry === undefined
        ? { ok: false, reason: "not_found" }
        : { ok: true, value: copyEntry(entry) };
    } catch {
      return { ok: false, reason: "storage_error" };
    }
  }

  async create(draft: ArchiveDraft): Promise<ServiceResult<ArchiveEntry>> {
    if (!valid(draft)) return { ok: false, reason: "invalid" };
    try {
      const inserted = await this.repository.create(copyEntry(draft));
      return { ok: true, value: copyEntry(inserted) };
    } catch {
      return { ok: false, reason: "storage_error" };
    }
  }

  async createMany(drafts: readonly ArchiveDraft[]): Promise<ServiceResult<ArchiveEntry[]>> {
    if (!Array.isArray(drafts) || !drafts.every(valid)) {
      return { ok: false, reason: "invalid" };
    }
    if (drafts.length === 0) return { ok: true, value: [] };
    try {
      const inserted = await this.repository.createMany(drafts.map(copyEntry).reverse());
      return { ok: true, value: inserted.map(copyEntry) };
    } catch {
      return { ok: false, reason: "storage_error" };
    }
  }
}

