import { ArchiveService } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  assert(Object.is(actual, expected), `${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  equal(JSON.stringify(actual), JSON.stringify(expected), message);
}

async function run(): Promise<void> {
  let calls = 0;
  let receivedCreate: any;
  let receivedMany: any;
  const stored = { id: 'a', title: 'Alpha', rank: 1, tags: ['one'] };
  const repository = {
    async list() { calls++; return [stored]; },
    async find(id: string) { calls++; return id === 'a' ? stored : undefined; },
    async create(draft: any) { calls++; receivedCreate = draft; return draft; },
    async createMany(drafts: any[]) { calls++; receivedMany = drafts; return drafts; }
  };
  const service = new ArchiveService(repository as any);

  const listed: any = await service.list();
  equal(listed.ok, true, 'list succeeds');
  deepEqual(listed.value, [stored], 'list preserves repository order and data');
  assert(listed.value[0] !== stored && listed.value[0].tags !== stored.tags, 'list copies repository records and arrays');
  listed.value[0].title = 'mutated';
  listed.value[0].tags.push('mutated');
  equal(stored.title, 'Alpha', 'returned record does not alias repository record');
  deepEqual(stored.tags, ['one'], 'returned tags do not alias repository tags');

  const found: any = await service.find('a');
  equal(found.ok, true, 'find succeeds');
  assert(found.value !== stored && found.value.tags !== stored.tags, 'find copies repository result');
  const missing: any = await service.find('missing');
  deepEqual(missing, { ok: false, reason: 'not_found' }, 'missing entry is reported');

  const draft: any = { id: 'b', title: 'Beta', rank: 0, tags: ['new'] };
  const created: any = await service.create(draft);
  equal(created.ok, true, 'create succeeds');
  assert(receivedCreate !== draft && receivedCreate.tags !== draft.tags, 'create copies input before repository call');
  assert(created.value !== receivedCreate && created.value.tags !== receivedCreate.tags, 'create copies repository output');
  draft.tags[0] = 'changed';
  deepEqual(created.value.tags, ['new'], 'created value is independent of input');

  const beforeInvalid = calls;
  const invalidDrafts: any[] = [
    { id: '', title: 'Title', rank: 0, tags: [] },
    { id: 'id', title: '', rank: 0, tags: [] },
    { id: 'id', title: 'Title', rank: -1, tags: [] },
    { id: 'id', title: 'Title', rank: 1.5, tags: [] },
    { id: 'id', title: 'Title', rank: 0, tags: [''] }
  ];
  for (const invalid of invalidDrafts) {
    deepEqual(await service.create(invalid), { ok: false, reason: 'invalid' }, 'invalid create is rejected');
  }
  equal(calls, beforeInvalid, 'invalid creates do not call repository');

  const emptyCalls = calls;
  const empty: any = await service.createMany([]);
  deepEqual(empty, { ok: true, value: [] }, 'empty batch succeeds');
  equal(calls, emptyCalls, 'empty batch avoids repository call');

  const batch: any[] = [
    { id: 'c', title: 'Third', rank: 2, tags: ['c'] },
    { id: 'd', title: 'Fourth', rank: 3, tags: ['d'] }
  ];
  const many: any = await service.createMany(batch);
  deepEqual(many.value.map((entry: any) => entry.id), ['c', 'd'], 'batch order is preserved');
  assert(receivedMany !== batch && receivedMany[0] !== batch[0] && receivedMany[0].tags !== batch[0].tags, 'batch input is deeply copied');
  assert(many.value !== receivedMany && many.value[0] !== receivedMany[0] && many.value[0].tags !== receivedMany[0].tags, 'batch output is deeply copied');

  const beforeInvalidBatch = calls;
  deepEqual(await service.createMany([batch[0], invalidDrafts[0]]), { ok: false, reason: 'invalid' }, 'one invalid draft rejects entire batch');
  equal(calls, beforeInvalidBatch, 'invalid batch avoids repository call');

  const failing = new ArchiveService({
    async list() { throw new Error('disk'); },
    async find() { throw new Error('disk'); },
    async create() { throw new Error('disk'); },
    async createMany() { throw new Error('disk'); }
  } as any);
  for (const result of [
    await failing.list(),
    await failing.find('x'),
    await failing.create({ id: 'x', title: 'X', rank: 0, tags: [] }),
    await failing.createMany([{ id: 'x', title: 'X', rank: 0, tags: [] }])
  ] as any[]) {
    deepEqual(result, { ok: false, reason: 'storage_error' }, 'repository exception becomes storage_error');
  }
}

void run();

